-- Open Exercise DB snapshot 80b98f38721a88119b860e0e0e969bf1592c2525 (322 exercises).
-- MIT licensed; see THIRD_PARTY_NOTICES.md.
ALTER TABLE movements ADD COLUMN IF NOT EXISTS source_exercise_id TEXT REFERENCES exercise_library(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS movements_source_exercise_id_idx ON movements (source_exercise_id);
CREATE UNIQUE INDEX IF NOT EXISTS movements_shared_source_unique ON movements (source_exercise_id) WHERE trainer_id IS NULL AND source_exercise_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS movements_trainer_source_unique ON movements (trainer_id, source_exercise_id) WHERE trainer_id IS NOT NULL AND source_exercise_id IS NOT NULL;

INSERT INTO exercise_library (id, name, description, difficulty, category, equipment, primary_muscle, secondary_muscles, muscle_intensity, updated_at)
SELECT source.id, source.name, source.description, source.difficulty, source.category, source.equipment, source.primary_muscle, source.secondary_muscles, source.muscle_intensity, NOW()
FROM jsonb_to_recordset($openexercisedb$[{"id":"45_degree_bicycle_twist_knee_to_elbow","name":"45_degree_bicycle_twist_knee_to_elbow","description":"A dynamic core exercise combining trunk rotation and hip flexion. Touch the opposite knee with your elbow at a 45-degree angle for maximum oblique activation. An excellent choice for a sculpted waist and a stable core.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Obliques","secondary_muscles":["Rectus Abdominis","Hip Flexors","Anterior Deltoid"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S2","calves":"T1","legs_quads":"S4","cardio":"S3"}},{"id":"45_degree_bicycle_twisting","name":"45_degree_bicycle_twisting","description":"A trunk twist at a 45-degree angle with a leg movement that simulates cycling. The exercise targets the entire abdominal wall with an emphasis on control and rotational strength. Get ready for a burning sensation in your core!","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Rectus Abdominis","secondary_muscles":["Obliques","Hip Flexors"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S2","calves":"T1","legs_quads":"S4","cardio":"S3"}},{"id":"45_degree_side_bend","name":"45_degree_side_bend","description":"An isolation exercise for the lateral abdominal muscles that improves lateral spinal mobility. Controlled side bends strengthen the waist and increase core stability. Simple yet extremely effective for defining the 'obliques'.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Obliques","secondary_muscles":["Quadratus Lumborum","Erector Spinae"],"muscle_intensity":{"abs_/_core":"P8","stretching":"S3","back":"S4"}},{"id":"90_degree_heel_touch","name":"90_degree_heel_touch","description":"A targeted exercise for the lateral abdominal muscles where you touch your heels from a lying position. Keeping the upper back raised maintains constant tension in the core. An ideal finisher for any ab workout.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Obliques","secondary_muscles":["Rectus Abdominis (Upper)"],"muscle_intensity":{"abs_/_core":"P8"}},{"id":"90_degree_heels_touch","name":"90_degree_heels_touch","description":"Focus on lateral core strength with alternating heel touches at a 90-degree angle. The exercise builds stability and helps shape the side of the abdomen. Controlled movement is the key to success.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Obliques","secondary_muscles":["Rectus Abdominis"],"muscle_intensity":{"abs_/_core":"P8"}},{"id":"alternate_arm_leg_plank","name":"alternate_arm_leg_plank","description":"An advanced plank variation that demands exceptional balance and core stability. By raising the opposite arm and leg, we challenge the entire posterior chain and deep abdominal muscles. Test your coordination and strength!","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Core","secondary_muscles":["Gluteus Maximus","Erector Spinae","Deltoids"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S5","calves":"T2","triceps":"S3","legs_quads":"S4","glutes":"S6","legs_hamstrings":"S3","back":"S5","cardio":"S2"}},{"id":"alternate_arm_leg_plank_hold","name":"alternate_arm_leg_plank_hold","description":"An isometric plank variation with raised limbs for maximum static strength. This exercise teaches the body how to maintain core rigidity under asymmetric load. A key exercise for anyone who wants an unbreakable core.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Core","secondary_muscles":["Gluteus Maximus","Erector Spinae","Shoulder Stabilizers"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S5","calves":"T2","triceps":"S3","legs_quads":"S4","glutes":"S6","legs_hamstrings":"S3","back":"S5","cardio":"S1"}},{"id":"alternate_biceps_curl_resistance_band","name":"alternate_biceps_curl_resistance_band","description":"An effective isolation exercise for the biceps using a resistance band. The band provides progressive resistance, meaning the effort is greatest at the top of the contraction. Great for safe and effective arm training anywhere.","difficulty":4,"category":"strength","equipment":["resistance band"],"primary_muscle":"Biceps Brachii","secondary_muscles":["Brachialis","Brachioradialis"],"muscle_intensity":{"abs_/_core":"S2","biceps":"P9","forearms_(front)":"S5"}},{"id":"alternate_biceps_curl_standing_dumbbells","name":"alternate_biceps_curl_standing_dumbbells","description":"A classic for strong arms! Alternating dumbbell curls allow better focus on each muscle individually and prevent asymmetry. The standing position additionally engages the core stabilizer muscles.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps Brachii","secondary_muscles":["Brachialis","Forearms"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S2","biceps":"P9","forearms_(front)":"S4"}},{"id":"alternate_front_kick_in_place","name":"alternate_front_kick_in_place","description":"A dynamic aerobic exercise that strengthens the legs and raises the heart rate. Alternating front kicks improve hamstring flexibility and quad strength. Great for warm-up or metabolic training.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":["Hip Flexors","Abdominals","Gastrocnemius"],"muscle_intensity":{"abs_/_core":"S5","calves":"S3","legs_quads":"P8","glutes":"S4","legs_hamstrings":"S3","stretching":"S4","cardio":"P7"}},{"id":"alternate_hammer_curl_seated_dumbbells","name":"alternate_hammer_curl_seated_dumbbells","description":"The seated 'hammer' variation targets the deep muscles of the upper arm and forearm. A neutral grip reduces wrist stress and allows lifting heavier loads. Sitting prevents cheating with body sway.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Brachioradialis","secondary_muscles":["Biceps Brachii","Brachialis"],"muscle_intensity":{"abs_/_core":"S2","biceps":"P9","forearms_(front)":"P7"}},{"id":"alternate_hammer_curl_standing_dumbbells","name":"alternate_hammer_curl_standing_dumbbells","description":"A versatile exercise for arm thickness and grip strength. The neutral hand position strongly activates the brachialis and forearms, giving the arms a fuller look. The standing position promotes full-body stability.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Brachialis","secondary_muscles":["Biceps Brachii","Brachioradialis","Core"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S2","biceps":"P9","forearms_(front)":"P7"}},{"id":"alternate_heel_touches","name":"alternate_heel_touches","description":"A simple yet effective exercise for defining the 'six-pack' and lateral muscles. A slight lift of the head and scapulae activates the upper abs, while the side movement takes care of the waist. Ideal for quick core workouts.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Obliques","secondary_muscles":["Rectus Abdominis"],"muscle_intensity":{"abs_/_core":"P9","cardio":"S2"}},{"id":"alternate_lying_floor_leg_raise","name":"alternate_lying_floor_leg_raise","description":"An excellent exercise for the lower abdominal muscles and pelvic stabilization. Alternating leg lowering requires controlled strength and prevents lower back pain. Build your core endurance with each rep.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Lower Rectus Abdominis","secondary_muscles":["Hip Flexors","Obliques"],"muscle_intensity":{"abs_/_core":"P9","legs_quads":"S5","stretching":"S2"}},{"id":"alternate_oblique_crunch","name":"alternate_oblique_crunch","description":"A combined trunk flexion with rotation targeting the front and side abdominal muscles simultaneously. This exercise is key for developing functional core strength and rotational stability. The emphasis is on the contraction, not the height of the rise.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Obliques","secondary_muscles":["Rectus Abdominis"],"muscle_intensity":{"abs_/_core":"P9"}},{"id":"alternate_superman","name":"alternate_superman","description":"An exercise for the entire posterior chain that improves posture and strengthens the lower back. By alternately raising the opposite arm and leg, we safely strengthen the spinal stabilizers. Ideal for preventing pain caused by prolonged sitting.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Erector Spinae","secondary_muscles":["Gluteus Maximus","Hamstrings","Rear Deltoids"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S4","glutes":"S6","legs_hamstrings":"S5","stretching":"S2","back":"P9"}},{"id":"alternating_biceps_curl_seated_dumbbells","name":"alternating_biceps_curl_seated_dumbbells","description":"Seated dumbbell curls allow complete bicep isolation without the help of the lower body. Alternating execution ensures even development of both arms. An excellent exercise for those who want to emphasize the 'peak' of the bicep.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps Brachii","secondary_muscles":["Brachialis","Brachioradialis"],"muscle_intensity":{"abs_/_core":"S2","shoulders":"S1","biceps":"P9","forearms_(front)":"S4"}},{"id":"alternating_biceps_hammer_curls_resistance_band","name":"alternating_biceps_hammer_curls_resistance_band","description":"Combine the neutral hammer grip with the progressive resistance of a band for strong arms and forearms. This exercise is joint-friendly and provides constant effort through the full range of motion. A quick and effective tool for toning arms.","difficulty":4,"category":"strength","equipment":["resistance band"],"primary_muscle":"Brachialis","secondary_muscles":["Biceps Brachii","Forearms"],"muscle_intensity":{"abs_/_core":"S3","biceps":"P9","forearms_(front)":"P7"}},{"id":"alternating_hamstring_curl","name":"alternating_hamstring_curl","description":"Focus on the back of the thighs with this isolation exercise. Alternating leg curls powerfully activate the hamstrings and glutes, which is crucial for knee stability. An excellent complement to front-leg exercises.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Hamstrings","secondary_muscles":["Gluteus Maximus","Gastrocnemius"],"muscle_intensity":{"abs_/_core":"S3","calves":"S4","glutes":"S6","legs_hamstrings":"P9","stretching":"S2","back":"S2","cardio":"S3"}},{"id":"alternating_hamstring_curl_with_punch","name":"alternating_hamstring_curl_with_punch","description":"A dynamic exercise that combines leg strength with arm coordination. While strengthening the hamstrings, forward punches raise the heart rate and engage the shoulder girdle. A perfect 'burn' exercise for the whole body!","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Hamstrings","secondary_muscles":["Anterior Deltoid","Core","Glutes"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S6","calves":"S4","chest":"S3","triceps":"S4","glutes":"S6","legs_hamstrings":"P8","back":"S3","cardio":"P8"}},{"id":"alternating_leg_lifts","name":"alternating_leg_lifts","description":"An exceptional exercise for the lower abdominal muscles and core stabilization. Controlled lifting and lowering of the legs will strengthen the waist and improve pelvic control. The exercise is gentle on the spine when performed with proper technique.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Rectus Abdominis (Lower)","secondary_muscles":["Hip Flexors","Transverse Abdominis"],"muscle_intensity":{"abs_/_core":"P9","legs_quads":"S4","stretching":"S3"}},{"id":"alternating_lunge_with_rotation","name":"alternating_lunge_with_rotation","description":"A functional exercise that strengthens the legs while challenging core stability through rotation. The lunge builds strong thighs and glutes, and the twist provides spinal mobility. Great for athletes and recreational exercisers.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":["Gluteus Maximus","Obliques","Hamstrings"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S2","calves":"S3","legs_quads":"P9","glutes":"S7","legs_hamstrings":"S5","stretching":"S3","back":"S4","cardio":"S5"}},{"id":"alternating_oblique_sit_ups","name":"alternating_oblique_sit_ups","description":"A classic ab exercise with an added twist that targets your oblique muscles. By alternately touching the opposite knee, you will sculpt your waist and strengthen core stability. A perfect choice for functional core strength.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Obliques","secondary_muscles":["Rectus Abdominis","Hip Flexors"],"muscle_intensity":{"abs_/_core":"P9","legs_quads":"S2","cardio":"S3"}},{"id":"alternating_plank_lunge","name":"alternating_plank_lunge","description":"A dynamic combination of plank and lunge that simultaneously challenges your stability and hip mobility. The exercise activates the whole body, with emphasis on the core and lower body. Great for warm-up or metabolic training.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":["Gluteus Maximus","Core","Hip Flexors"],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S4","calves":"S2","triceps":"S3","legs_quads":"P8","glutes":"S7","legs_hamstrings":"S4","stretching":"S5","cardio":"S6"}},{"id":"alternating_step_out","name":"alternating_step_out","description":"A low-intensity yet effective exercise for lateral stability and leg activation. Alternating controlled side steps strengthen hip stabilizers and improve balance. Suitable for all fitness levels.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Gluteus Medius","secondary_muscles":["Quadriceps","Adductors"],"muscle_intensity":{"abs_/_core":"S3","calves":"S2","legs_quads":"P7","glutes":"P7","legs_hamstrings":"S3","cardio":"S4"}},{"id":"alternating_superman","name":"alternating_superman","description":"A key exercise for a strong lower back and better posture. By alternately raising the opposite arm and leg, we safely strengthen the entire posterior chain. The exercise is ideal for those who sit a lot.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Erector Spinae","secondary_muscles":["Gluteus Maximus","Hamstrings","Rear Deltoids"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S3","glutes":"S6","legs_hamstrings":"S5","back":"P9"}},{"id":"archer_pull_up","name":"archer_pull_up","description":"An advanced pull-up variation that simulates drawing a bow and heavily loads one side of the body at a time. This exercise builds exceptional back and arm strength and is an excellent step toward a one-arm pull-up. Requires a high degree of strength and control.","difficulty":9,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Latissimus Dorsi","secondary_muscles":["Biceps Brachii","Rear Deltoids","Brachialis"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S6","stretching":"S4","back":"P10","biceps":"P8","forearms_(front)":"S7"}},{"id":"archer_push_up","name":"archer_push_up","description":"An advanced push-up form where one arm takes most of the load and the other serves as support. The exercise develops unilateral chest strength and improves shoulder stability. Visually impressive and extremely effective.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Pectoralis Major","secondary_muscles":["Triceps Brachii","Anterior Deltoid","Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S6","chest":"P10","triceps":"S7","glutes":"S3","stretching":"S3"}},{"id":"arnold_press_cable_resistance_band_standing","name":"arnold_press_cable_resistance_band_standing","description":"A variation of the Arnold Press using a resistance band to provide constant tension in the shoulders. The rotation during the movement activates all three parts of the shoulder muscle for complete shoulder development. The standing position additionally engages core stabilization.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Deltoids","secondary_muscles":["Triceps Brachii","Serratus Anterior","Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"P9","chest":"S3","triceps":"P7","back":"S3","biceps":"S2"}},{"id":"arnold_press_dumbbell","name":"arnold_press_dumbbell","description":"The legendary shoulder exercise popularized by Arnold Schwarzenegger. Rotating the dumbbells during the press achieves maximum stimulation of the front and middle shoulders. One of the best exercises for building 'boulder shoulders'.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Deltoids","secondary_muscles":["Triceps Brachii","Upper Pectoralis","Trapezius"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"P10","chest":"S3","triceps":"P7","biceps":"S2"}},{"id":"around_the_world_superman_hold","name":"around_the_world_superman_hold","description":"An advanced static exercise for the posterior chain with added arm movement. While maintaining the Superman position, circling the arms activates scapular stabilizers and the entire back. Great for strength, endurance, and shoulder mobility.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Erector Spinae","secondary_muscles":["Gluteus Maximus","Rhomboids","Deltoids"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"P7","glutes":"P8","legs_hamstrings":"S6","back":"P9"}},{"id":"back_lever","name":"back_lever","description":"A highly advanced static gymnastics element that requires exceptional strength in the entire posterior chain and shoulders. Hold the body horizontally below the bar, facing downward. A symbol of ultimate body control.","difficulty":10,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back (Full)","secondary_muscles":["Core","Rear Deltoids","Forearms"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"P10","chest":"S6","triceps":"S4","legs_quads":"S3","glutes":"S6","legs_hamstrings":"S4","stretching":"S5","back":"P10","biceps":"S7","forearms_(front)":"S8"}},{"id":"back_squeeze","name":"back_squeeze","description":"An isolation exercise to activate the muscles between the shoulder blades, which helps correct posture. By simply squeezing the back, you improve body awareness and strengthen the rhomboids. Ideal for active breaks during work.","difficulty":2,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Rhomboids","secondary_muscles":["Trapezius (Middle)","Rear Deltoids"],"muscle_intensity":{"shoulders":"S4","stretching":"S3","back":"P9"}},{"id":"barbell_alternate_biceps_curl","name":"barbell_alternate_biceps_curl","description":"Alternating barbell curls allow better focus on each arm individually. This exercise builds bicep mass and strength and helps correct asymmetries. A classic in arm training.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps Brachii","secondary_muscles":["Brachialis","Forearms"],"muscle_intensity":{"abs_/_core":"S3","biceps":"P10","forearms_(front)":"S6"}},{"id":"barbell_behind_neck_push_press","name":"barbell_behind_neck_push_press","description":"An explosive shoulder exercise where you use your legs to assist when pressing the bar from behind the neck. This technique allows you to handle greater loads and develop dynamic strength. Requires good shoulder mobility.","difficulty":8,"category":"strength","equipment":["weights"],"primary_muscle":"Deltoids","secondary_muscles":["Triceps Brachii","Quadriceps","Trapezius"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"P10","calves":"S4","triceps":"P8","legs_quads":"S5","glutes":"S4","stretching":"S4","back":"S5","cardio":"S4"}},{"id":"barbell_bench_lateral_step_up","name":"barbell_bench_lateral_step-up","description":"A complex exercise combining a lateral step-up onto a bench with barbell load. Extremely effective for developing strong legs, glutes, and core stabilizers. Requires a high degree of balance and coordination.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":["Gluteus Maximus","Adductors","Erector Spinae"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S4","calves":"S5","legs_quads":"P10","glutes":"P9","legs_hamstrings":"S6","back":"S5","cardio":"S5"}},{"id":"barbell_bench_press","name":"barbell_bench_press","description":"The gold standard for upper body strength. The flat barbell bench press allows the greatest possible load on the chest, shoulders, and triceps. An indispensable exercise for anyone who wants to develop chest muscle mass.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Pectoralis Major","secondary_muscles":["Anterior Deltoid","Triceps Brachii"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S7","chest":"P10","triceps":"P8"}},{"id":"barbell_bench_squat","name":"barbell_bench_squat","description":"A squat variation where you lightly touch the bench with your glutes, ensuring consistent depth and safety. An excellent exercise for learning proper squat technique under load. Strengthens the entire lower body with a strong emphasis on the glutes.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":["Gluteus Maximus","Hamstrings","Erector Spinae"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S3","calves":"S4","legs_quads":"P10","glutes":"P9","legs_hamstrings":"S7","back":"S7","cardio":"S4"}},{"id":"barbell_bent_over_row","name":"barbell_bent_over_row","description":"One of the most effective exercises for back thickness and width. Bent-over barbell rows activate the lats, rhomboids, and traps, while also demanding strong lower back stabilization. A staple of every back workout.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Latissimus Dorsi","secondary_muscles":["Rhomboids","Erector Spinae","Biceps Brachii"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S5","glutes":"S4","legs_hamstrings":"S6","back":"P10","biceps":"P7","forearms_(front)":"S6"}},{"id":"barbell_bicep_curl_normal_grip","name":"barbell_bicep_curl_normal_grip","description":"A basic barbell bicep exercise with a standard shoulder-width grip. Allows the use of heavier loads for maximum mechanical tension and muscle growth. The key to strong and defined arms.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps Brachii","secondary_muscles":["Brachialis","Brachioradialis"],"muscle_intensity":{"abs_/_core":"S3","biceps":"P10","forearms_(front)":"S6"}},{"id":"barbell_biceps_curl","name":"barbell_biceps_curl","description":"The most popular bicep training exercise. With a barbell, you can effectively isolate the biceps brachii and develop exceptional strength. Simple yet relentlessly effective — a classic.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps Brachii","secondary_muscles":["Brachialis","Forearms"],"muscle_intensity":{"abs_/_core":"S3","biceps":"P10","forearms_(front)":"S6"}},{"id":"barbell_bulgarian_split_squat","name":"barbell_bulgarian_split_squat","description":"An extremely demanding leg exercise where the rear leg is elevated on a bench while holding a barbell. This asymmetric squat drastically activates the glutes and stabilizing muscles. Prepare for a serious challenge for balance and strength.","difficulty":8,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":["Gluteus Maximus","Hamstrings","Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S3","calves":"S5","legs_quads":"P10","glutes":"P10","legs_hamstrings":"S7","stretching":"S4","back":"S6","cardio":"S5"}},{"id":"barbell_calf_jump","name":"barbell_calf_jump","description":"An explosive calf exercise combining jumps with barbell load. Develops reactive strength and definition in the lower legs. Ideal for athletes who want to improve their vertical jump.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Gastrocnemius (Calves)","secondary_muscles":["Soleus","Quadriceps","Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S3","calves":"P10","legs_quads":"S5","glutes":"S4","back":"S5","cardio":"S7"}},{"id":"barbell_clean_and_jerk","name":"barbell_clean_and_jerk","description":"The royal Olympic lift requiring a combination of strength, speed, coordination, and technique. Moving the bar from the floor to overhead in one fluid motion activates every muscle in the body. The highest level of athletic performance.","difficulty":10,"category":"strength","equipment":["weights"],"primary_muscle":"Full Body","secondary_muscles":["Quadriceps","Hamstrings","Deltoids","Erector Spinae"],"muscle_intensity":{"abs_/_core":"P8","shoulders":"P9","calves":"S6","chest":"S4","triceps":"S7","legs_quads":"P10","glutes":"P10","legs_hamstrings":"P9","stretching":"S6","back":"P10","biceps":"S5","cardio":"P8","forearms_(front)":"S8"}},{"id":"barbell_clean_and_press","name":"barbell_clean_and_press","description":"An explosive full-body Olympic movement combining a clean from the floor with a push press overhead. It develops total-body power, coordination, and cardiovascular conditioning in a single compound lift.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"barbell_clean_deadlift","name":"barbell_clean_deadlift","description":"A pulling variation that reinforces the initial pull position of the clean. Focusing on leg drive and a neutral spine, it builds posterior chain strength and improves Olympic lifting technique.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"barbell_clean_pull","name":"barbell_clean_pull","description":"A powerful pulling movement from the floor that trains the explosive extension of the hips, knees, and ankles without completing the full clean. Essential for developing barbell speed and pulling strength.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"barbell_curl","name":"barbell_curl","description":"A fundamental barbell bicep exercise performed with both hands simultaneously for maximum loading. It builds bicep mass and strength efficiently, allowing heavier loads than dumbbell variations.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"barbell_deadlift","name":"barbell_deadlift","description":"The queen of all strength exercises for full posterior chain development. The deadlift engages almost every muscle in the body, promotes a strong hormonal response, and builds unbreakable back and leg strength.","difficulty":8,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":["Glutes","Hamstrings","Forearms (Front)","Abs / Core"],"muscle_intensity":{"abs_/_core":"S7","shoulders":"S4","calves":"S4","legs_quads":"S6","glutes":"P9","legs_hamstrings":"P9","back":"P9","biceps":"S3","cardio":"S4","forearms_(front)":"P8"}},{"id":"barbell_decline_shrug","name":"barbell_decline_shrug","description":"A shrug variation performed on a decline bench that shifts the emphasis to the lower trapezius and rhomboids. Excellent for improving posture and developing the often-neglected lower portion of the traps.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"barbell_drag_biceps_curl","name":"barbell_drag_biceps_curl","description":"A unique curl where the bar drags up the torso rather than arcing outward. This keeps constant tension on the biceps throughout the movement and reduces front deltoid involvement.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"barbell_drag_curl","name":"barbell_drag_curl","description":"A variation of the barbell curl where the bar travels in a straight vertical line close to the body. This technique maximally isolates the biceps by minimizing shoulder flexion.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"barbell_front_chest_squat","name":"barbell_front_chest_squat","description":"A front squat variation with the bar held across the chest. The forward weight placement demands an upright torso and deeply activates the quadriceps and upper back stabilizers.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5","legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"barbell_front_raise","name":"barbell_front_raise","description":"An isolation exercise for the front deltoids using a barbell. Lifting with both arms simultaneously allows greater load and better symmetry than dumbbell front raises.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":[],"muscle_intensity":{"shoulders":"P8","triceps":"S3"}},{"id":"barbell_front_squat","name":"barbell_front_squat","description":"A squat with the barbell held across the front of the shoulders. The forward load forces an upright torso, maximally loading the quadriceps while also challenging upper back strength.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"barbell_full_clean","name":"barbell_full_clean","description":"The complete clean movement from the floor to the front rack position. It develops explosive power through the entire posterior chain and requires precise coordination and timing.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"barbell_full_squat","name":"barbell_full_squat","description":"A deep barbell back squat performed with full range of motion until the hips pass below the knees. It maximally develops the quadriceps, glutes, and hamstrings while improving hip mobility.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"barbell_glute_bridge","name":"barbell_glute_bridge","description":"A hip thrust variation performed flat on the floor, targeting the glutes and hamstrings. The barbell across the hips allows heavy loading for maximum glute development.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"barbell_hip_thrust","name":"barbell_hip_thrust","description":"One of the most effective exercises for glute hypertrophy. With the upper back on a bench and a barbell across the hips, you drive powerfully upward to fully contract the glutes.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"barbell_lap_curl","name":"barbell_lap_curl","description":"A seated bicep curl performed with the elbows resting on the thighs. This position isolates the biceps completely, eliminating any body swing or momentum.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"barbell_preacher_curl","name":"barbell_preacher_curl","description":"A bicep curl performed on a preacher bench that prevents any elbow movement during the lift. This strict isolation maximizes the stretch and contraction of the biceps for peak development.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"barbell_rack_pull","name":"barbell_rack_pull","description":"A partial deadlift performed from a rack set at knee height or above. It allows heavier loads than a full deadlift, specifically targeting the upper back, traps, and lockout strength.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"barbell_reverse_biceps_curl","name":"barbell_reverse_biceps_curl","description":"A curl with an overhand (pronated) grip that shifts the emphasis to the brachioradialis and forearms. It builds grip strength and adds thickness to the outer portion of the upper arm.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"barbell_reverse_deadlift","name":"barbell_reverse_deadlift","description":"A deadlift variation with a reverse (overhand) grip on both hands. It challenges grip strength and forearm endurance while maintaining the same posterior chain benefits as a conventional deadlift.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"barbell_reverse_grip_bench_press","name":"barbell_reverse_grip_bench_press","description":"A bench press with an underhand (supinated) grip that shifts the emphasis from the lower chest to the upper chest and triceps. It also places less stress on the wrists and shoulders.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"barbell_romanian_deadlift","name":"barbell_romanian_deadlift","description":"A hip-hinge movement with a slight knee bend that specifically targets the hamstrings and glutes. Unlike a conventional deadlift, the bar does not touch the floor between reps.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Hamstrings","secondary_muscles":[],"muscle_intensity":{"glutes":"S6","legs_hamstrings":"P8","back":"S4","biceps":"S4"}},{"id":"barbell_shrugs","name":"barbell_shrugs","description":"An isolation exercise for the upper trapezius muscles. By shrugging the barbell straight upward, you build thick, powerful traps that contribute to a strong upper back appearance.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"barbell_single_arm_biceps_curl","name":"barbell_single_arm_biceps_curl","description":"A unilateral barbell curl that trains each arm independently for balanced bicep development. Holding the bar with one hand increases the stability demand on the core and shoulder.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"barbell_situp","name":"barbell_situp","description":"A sit-up performed while holding a barbell across the chest or overhead for added resistance. The extra load increases the difficulty and builds greater abdominal strength.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"behind_neck_lat_pull_down_machine","name":"behind_neck_lat_pull_down_machine","description":"A lat pulldown variation where the bar is pulled behind the neck. It targets the upper lats and rhomboids with a different angle, though shoulder mobility is required.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"behind_neck_press_resistance_band_cable","name":"behind_neck_press_resistance_band_cable","description":"An overhead press variation with a cable or band where the resistance comes from behind the neck. It challenges the rear deltoids and upper trapezius through a unique angle.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"bench_alternating_step_ups","name":"bench_alternating_step_ups","description":"A unilateral leg exercise stepping alternately onto a bench. It builds quad and glute strength while improving balance, coordination, and single-leg stability.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5","legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bench_bulgarian_split_squats_left","name":"bench_bulgarian_split_squats_left","description":"A Bulgarian split squat performed with the left leg forward and the right foot elevated on a bench. It unilaterally develops the left quad, glute, and hip stabilizers.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5","legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bench_bulgarian_split_squats_right","name":"bench_bulgarian_split_squats_right","description":"A Bulgarian split squat performed with the right leg forward and the left foot elevated on a bench. It unilaterally develops the right quad, glute, and hip stabilizers.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5","legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bench_dip_knees_bent","name":"bench_dip_(knees_bent)","description":"A tricep dip with the hands on a bench and knees bent for reduced resistance. An accessible variation that builds tricep and shoulder strength for beginners.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"bench_dip_on_floor","name":"bench_dip_on_floor","description":"A tricep dip with the hands on the floor behind the body and feet extended forward. It isolates the triceps while placing minimal stress on the shoulder joints.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"bench_pull_ups","name":"bench_pull-ups","description":"An inverted row variation performed under a bench. Lying beneath the bench and pulling the chest up trains the back, biceps, and rear deltoids in a horizontal pulling plane.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5","glutes":"T2","back":"P8","biceps":"S4"}},{"id":"bench_reverse_plank_hold","name":"bench_reverse_plank_hold","description":"An isometric hold with the hands on a bench behind you and the body extended in a reverse plank. It strengthens the glutes, hamstrings, and posterior shoulder muscles.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2","chest":"P8","triceps":"S5"}},{"id":"bench_triceps_dip_leg_curls","name":"bench_triceps_dip_leg_curls","description":"A tricep dip off a bench combined with a leg curl movement to simultaneously engage the hamstrings. This combination exercise is efficient for training the arms and posterior chain together.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"P8","biceps":"P9","forearms_(front)":"S4"}},{"id":"bench_triceps_dip_straight_legs","name":"bench_triceps_dip_straight_legs","description":"A tricep dip with hands on a bench and legs straight out in front. The straight-leg position increases the resistance compared to the bent-knee variation.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"P8"}},{"id":"bicep_curl_low_cable_machine_normal_grip","name":"bicep_curl_low_cable_machine_normal_grip","description":"A bicep curl performed on a low cable machine with a standard underhand grip. The cable provides constant tension throughout the full range of motion for maximum bicep stimulation.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"biceps_curl_cable","name":"biceps_curl_cable","description":"A bicep curl using a cable machine that maintains constant resistance throughout the movement. The cable angle can be adjusted for different training effects and muscle emphasis.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"bicycles_crunches","name":"bicycles_crunches","description":"An extremely effective exercise for the upper, lower, and lateral abdominal muscles simultaneously. The leg movement simulates cycling, which combined with trunk rotation creates constant core tension.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Obliques","Hip Flexors"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S2","calves":"T2","legs_quads":"S4","cardio":"S4"}},{"id":"body_saw_plank","name":"body_saw_plank","description":"An advanced plank variation where you slide or rock forward and backward on your forearms. It increases the demand on the core stabilizers far beyond a standard plank.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"bodyweight_calf_raises","name":"bodyweight_calf_raises","description":"A simple yet effective isolation exercise for the calf muscles performed with no added weight. It can be done anywhere and is ideal for building calf endurance and definition.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"bodyweight_forward_lunge","name":"bodyweight_forward_lunge","description":"A classic unilateral leg exercise stepping forward into a lunge position. It develops quad, glute, and hamstring strength while improving balance and hip flexibility.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bodyweight_full_squat_with_overhead_front_raise","name":"bodyweight_full_squat_with_overhead_front_raise","description":"A compound exercise combining a full squat with an arm raise to the front at the top. It simultaneously works the legs, core, and anterior deltoids, making it an efficient full-body movement.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Shoulders","secondary_muscles":[],"muscle_intensity":{"shoulders":"P8","triceps":"S3","legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bodyweight_knee_thrust","name":"bodyweight_knee_thrust","description":"A dynamic exercise driving the knee forward and upward from a standing position. It activates the hip flexors and core while also raising the heart rate for cardiovascular conditioning.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"bodyweight_kneeling_push_up_row","name":"bodyweight_kneeling_push-up_row","description":"An excellent hybrid exercise that simultaneously strengthens the chest muscles and back stabilizers. Performing on the knees allows complete control of the movement, while the rowing simulation activates the core and inter-scapular muscles.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Back","Triceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S4","chest":"P8","triceps":"S5","glutes":"T2","back":"P8","biceps":"S4","cardio":"S3","forearms_(front)":"S3"}},{"id":"bodyweight_kneeling_sissy_squat","name":"bodyweight_kneeling_sissy_squat","description":"An isolation exercise that will literally 'burn' your quadriceps. With a controlled backward lean from a kneeling position, you create exceptional stretch and tension in the front thigh muscles without additional weights.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Abs / Core","Hip Flexors"],"muscle_intensity":{"abs_/_core":"S6","legs_quads":"P9","glutes":"S4","legs_hamstrings":"S3","stretching":"S5"}},{"id":"bodyweight_muscle_up","name":"bodyweight_muscle-up","description":"The ultimate test of upper body strength, combining an explosive pull-up with a powerful push. This exercise requires not only raw back and arm strength, but also excellent technique and coordination during the transition over the bar.","difficulty":10,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":["Triceps","Biceps","Shoulders","Chest"],"muscle_intensity":{"abs_/_core":"S7","shoulders":"S6","chest":"S6","triceps":"S7","back":"P10","biceps":"P8","cardio":"S5","forearms_(front)":"S8"}},{"id":"bodyweight_rear_lunge","name":"bodyweight_rear_lunge","description":"A classic for firm glutes and strong legs, friendlier on the knees than classic forward lunges. Stepping backward better activates the posterior chain muscles and improves your stability and balance.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Glutes","secondary_muscles":["Legs – Quads","Legs – Hamstrings"],"muscle_intensity":{"abs_/_core":"S4","calves":"S3","legs_quads":"P8","glutes":"P9","legs_hamstrings":"S7","stretching":"S4","cardio":"S5"}},{"id":"bodyweight_squat","name":"bodyweight_squat","description":"A fundamental exercise for anyone who wants functional lower body strength. The squat activates the largest muscle groups and improves hip mobility, which directly translates to better movement in everyday life.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Legs – Hamstrings","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","calves":"S3","legs_quads":"P9","glutes":"P8","legs_hamstrings":"S6","back":"S3","cardio":"S4"}},{"id":"bodyweight_squats_hold","name":"bodyweight_squats_hold","description":"A squat with a pause held at the bottom position. The isometric hold eliminates the stretch reflex, forcing the muscles to generate force from a dead stop.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bodyweight_standing_military_press","name":"bodyweight_standing_military_press","description":"An overhead press performed standing without any equipment, using bodyweight leverage or a pike position. It targets the shoulders and triceps while demanding strong core stability.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"bodyweight_step_up_on_step_box","name":"bodyweight_step-up_on_step_box","description":"A unilateral leg exercise stepping up onto a box or step. It builds quad and glute strength while improving balance, and the height of the step adjusts the difficulty.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"box_jump","name":"box_jump","description":"An explosive exercise that develops your reactive strength and speed. Jumping onto a box will improve your athletic ability while also ensuring a high heart rate and intense calorie burn.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Calves","Cardio"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S3","calves":"P8","legs_quads":"P9","glutes":"P9","legs_hamstrings":"S7","cardio":"P9"}},{"id":"box_jump_squats","name":"box_jump_squats","description":"An explosive combination of a squat followed immediately by a jump onto a box. It develops both lower body strength and reactive power in a single movement.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"brazillian_crunches","name":"brazillian_crunches","description":"A dynamic trunk curl variation that, with an emphasis on rotation, targets your oblique muscles. Ideal for chiseling the 'V-line' and improving core stability in all planes of movement.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Obliques","Hip Flexors"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S3","legs_quads":"S3","cardio":"S5"}},{"id":"bridge___mountain_climber_cross_body","name":"bridge_-_mountain_climber_(cross_body)","description":"A hybrid exercise combining a glute bridge hold with cross-body mountain climbers. It challenges the core, glutes, and hip flexors simultaneously with a strong anti-rotation demand.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"S5","legs_quads":"S5","cardio":"P7"}},{"id":"bridge_with_alternating_leg_raise","name":"bridge_with_alternating_leg_raise","description":"A glute bridge where one leg is raised alternately while maintaining the hip position. It isolates the glutes and challenges pelvic stability and single-leg strength.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"bulgarian_split_squat","name":"bulgarian_split_squat","description":"A split squat with the rear foot elevated on a bench, placing nearly all the load on the front leg. It is one of the most effective exercises for unilateral leg strength and glute development.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bulgarian_split_squat_bodyweight_left","name":"bulgarian_split_squat_bodyweight_left","description":"The Bulgarian split squat with the right foot elevated, loading the left leg. Excellent for correcting strength imbalances and developing left-side quad and glute power.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"bulgarian_split_squat_bodyweight_right","name":"bulgarian_split_squat_bodyweight_right","description":"The Bulgarian split squat with the left foot elevated, loading the right leg. Excellent for correcting strength imbalances and developing right-side quad and glute power.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"burpee","name":"burpee","description":"The ultimate full-body conditioning exercise combining a squat, plank, push-up, and jump. Burpees build total-body strength and explosive power while maximizing calorie burn and cardiovascular output.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"calf_raise_clap","name":"calf_raise_clap","description":"An explosive calf raise variation where you jump slightly off the ground and clap the feet together. It develops reactive calf strength and coordination.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"calf_raise_leg_press_machine","name":"calf_raise_leg_press_machine","description":"A calf raise performed at the bottom of a leg press machine using the footplate for resistance. It allows heavy loading for maximum calf hypertrophy through a full range of motion.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"chair_triceps_dips","name":"chair_triceps_dips","description":"A tricep dip using a sturdy chair for support. An accessible exercise that effectively targets the triceps and anterior deltoids without any gym equipment.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Triceps","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","triceps":"P8"}},{"id":"chest_dip","name":"chest_dip","description":"A powerful parallel bar exercise focusing on the lower chest muscles. With proper forward trunk lean, you create a greater mechanical advantage for the chest, leading to a strong and broad chest.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Shoulders (Front)"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S7","chest":"P10","triceps":"P8","stretching":"S5","back":"S3","forearms_(front)":"S4"}},{"id":"chest_fly_high_to_low_resistance_band","name":"chest_fly_high_to_low_resistance_band","description":"A chest fly performed with a resistance band anchored high, pulling in a downward arc. This angle specifically targets the lower chest and provides constant tension throughout the movement.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"chest_lift_with_rotation","name":"chest_lift_with_rotation","description":"An excellent exercise for core stabilization and chest muscle activation at various angles. Trunk rotation at the top position increases the load on the lateral abdominal muscles and improves spinal mobility.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Chest","Obliques","Shoulders"],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S4","chest":"P7","triceps":"S4","stretching":"S3","back":"S3"}},{"id":"chest_pull_back","name":"chest_pull_back","description":"An effective posture correction exercise that opens the chest and strengthens the rear shoulder muscles. Simulating a pulling-back motion activates the inter-scapular muscles, crucial for anyone who sits a lot.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":["Shoulders (Rear)","Scapulae"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"P8","chest":"S4 (raztezanje)","triceps":"S3","glutes":"T2","stretching":"P7","back":"P9","biceps":"S4"}},{"id":"chest_tap_push_up","name":"chest_tap_push_up","description":"An advanced push-up variation that introduces an element of explosiveness and single-arm stabilization. Touching the chest at the top forces the core into critical stabilization while the chest muscles work under greater stress.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Abs / Core","Shoulders"],"muscle_intensity":{"abs_/_core":"S7","shoulders":"S6","chest":"P9","triceps":"S7","glutes":"S3","back":"S4","cardio":"S5","forearms_(front)":"S4"}},{"id":"chin_up","name":"chin_up","description":"Underhand-grip pull-ups are one of the best exercises for developing a massive back and strong biceps. The palm position allows greater use of arm strength, which helps achieve a full range of motion and strong lat contraction.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":["Biceps","Forearms (Front)","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S4","chest":"S3","stretching":"S5","back":"P10","biceps":"P9","cardio":"S2","forearms_(front)":"S7"}},{"id":"cluster","name":"cluster","description":"An advanced barbell technique involving multiple mini-sets within a single set, with brief rest between each rep. It allows greater total volume with near-maximal loads for strength and hypertrophy.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"cocoons","name":"cocoons","description":"A core exercise lying on your back where you simultaneously bring the knees to the chest and the torso up, wrapping around them. It powerfully targets both the upper and lower abdominal muscles.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"commando_pull_up","name":"commando_pull-up","description":"A pull-up variation where you grip the bar with a neutral grip, hands one in front of the other. You alternate bringing each side of the head to the bar, working the lats and biceps from different angles.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"cossack_squat","name":"cossack_squat","description":"A top exercise for lateral strength and mobility that simultaneously strengthens the legs and opens the hips. The lateral movement requires exceptional knee and ankle stability, crucial for athletic performance and injury prevention.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Hamstrings","Adductors (Inner Thigh)"],"muscle_intensity":{"abs_/_core":"S5","calves":"S4","legs_quads":"P9","glutes":"S8","legs_hamstrings":"S7","stretching":"P9","back":"S4","cardio":"S4"}},{"id":"crunch_arms_straight","name":"crunch_(arms_straight)","description":"A standard crunch with the arms extended straight overhead or out in front. The lengthened lever arm increases the difficulty and the demand on the rectus abdominis.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"crunch_floor","name":"crunch_floor","description":"The foundational abdominal crunch performed lying on the floor. Raising only the shoulder blades targets the upper rectus abdominis with minimal hip flexor involvement.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"curtsy_squat","name":"curtsy_squat","description":"A squat variation where one leg crosses behind the other in a curtsy motion, targeting the outer glutes and inner thighs. It improves lateral hip stability and builds a well-rounded glute.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"dead_hang_stretch","name":"dead_hang_stretch","description":"A therapeutic exercise for spinal decompression and increasing grip strength. Hanging from a bar releases tension in the back muscles and simultaneously improves shoulder girdle health.","difficulty":2,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Forearms (Front)","secondary_muscles":["Back (Stretching)","Shoulders"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S6","chest":"S4","stretching":"P10","back":"S5","forearms_(front)":"P9"}},{"id":"decline_push_up","name":"decline_push_up","description":"A push-up with the feet elevated on a bench or box. The inclined body angle shifts the emphasis to the upper chest and anterior deltoids for greater upper-body development.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"deep_push_up","name":"deep_push-up","description":"A push-up performed with the hands on elevated surfaces, allowing a greater range of motion at the bottom. The deeper stretch activates more chest muscle fibers for superior development.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"diamond_push_up","name":"diamond_push-up","description":"An intense push-up variation that primarily loads the triceps due to the narrow hand placement. The diamond shape of the hands changes the biomechanics of the movement, increasing activation of the inner chest and arms.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Triceps","secondary_muscles":["Chest","Shoulders (Front)"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S6","chest":"S8","triceps":"P10","forearms_(front)":"S4"}},{"id":"dips_between_chairs","name":"dips_between_chairs","description":"A tricep dip performed between two chairs. It is a practical, equipment-free way to build tricep and chest strength using bodyweight resistance.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"double_jump_squat","name":"double_jump_squat","description":"An explosive squat variation involving two consecutive jumps before landing. It develops exceptional lower body power and fast-twitch muscle fiber recruitment.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"dragonfly","name":"dragonfly","description":"An advanced bodyweight exercise where the body is suspended horizontally from a bench supported only by the shoulders. It builds extraordinary core and hip flexor strength.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"dumbbell_ab_crunch","name":"dumbbell_ab_crunch","description":"A weighted crunch holding a dumbbell on the chest for added resistance. The extra load increases the demand on the rectus abdominis for greater strength and definition.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"dumbbell_alternate_biceps_curl","name":"dumbbell_alternate_biceps_curl","description":"An alternating dumbbell curl targeting each bicep individually for balanced development. Alternating arms allows brief recovery and better focus on each contraction.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_arnold_press","name":"dumbbell_arnold_press","description":"A legendary exercise targeting all three heads of the shoulder muscle in a single movement. Rotating the weights from face-level to overhead increases time under tension and improves shoulder stabilization in all phases.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Triceps","Upper Back"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"P10","chest":"S3","triceps":"S7","back":"S4","biceps":"S3","forearms_(front)":"S4"}},{"id":"dumbbell_bench_press","name":"dumbbell_bench_press","description":"Dumbbell pressing allows a greater range of motion than a barbell, leading to better chest muscle activation. Since each arm works independently, this exercise is ideal for correcting muscular asymmetries and improving stabilization.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Shoulders (Front)"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S6","chest":"P10","triceps":"S8","glutes":"T2","stretching":"S4","back":"S4","forearms_(front)":"S5"}},{"id":"dumbbell_bench_squat","name":"dumbbell_bench_squat","description":"An excellent exercise for learning proper squat technique, where the bench serves as a safe touch point. Holding dumbbells increases leg load while also strengthening core stabilization.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Hamstrings","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S3","calves":"T2","legs_quads":"P9","glutes":"S7","legs_hamstrings":"S5","back":"S4","cardio":"S3","forearms_(front)":"S4"}},{"id":"dumbbell_bent_over_row","name":"dumbbell_bent-over_row","description":"One of the most effective exercises for back density and a strong grip. Bent-over dumbbell rows allow a greater range of motion and better isolation of the left and right sides of the back.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":["Biceps","Shoulders (Rear)","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S4","glutes":"T2","legs_hamstrings":"S3","back":"P9","biceps":"S6","forearms_(front)":"S5"}},{"id":"dumbbell_bicep_curl_to_shoulder_press","name":"dumbbell_bicep_curl_to_shoulder_press","description":"A complex exercise that connects bicep curls and overhead pressing in one fluid movement. Ideal for a time-efficient upper body workout and improving coordination.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Biceps","Triceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"P8","triceps":"S6","back":"S3","biceps":"P8","cardio":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_bulgarian_box_split_squat","name":"dumbbell_bulgarian_box_split_squat","description":"An infamously difficult exercise that will completely transform your legs and glutes. Elevating the rear leg on a box increases the load on the front leg and requires excellent balance.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Glutes","secondary_muscles":["Legs – Quads","Hamstrings","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S3","calves":"S4","legs_quads":"P9","glutes":"P10","legs_hamstrings":"S7","stretching":"S6","back":"S4","cardio":"P7","forearms_(front)":"S4"}},{"id":"dumbbell_bulgarian_split_squat","name":"dumbbell_bulgarian_split_squat","description":"Unilateral strength in its purest form. This dumbbell variation challenges the entire lower body and hip stabilizers, preventing muscular imbalances.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Glutes","secondary_muscles":["Legs – Quads","Hamstrings","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S3","calves":"S4","legs_quads":"P9","glutes":"P10","legs_hamstrings":"S7","stretching":"S6","back":"S4","cardio":"P7","forearms_(front)":"S4"}},{"id":"dumbbell_chest_press_decline","name":"dumbbell_chest_press_decline","description":"A specific exercise emphasizing the lower chest muscles. Due to the decline angle, you can often press greater weights, promoting faster chest growth and strength.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Shoulders (Front)"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S5","chest":"P10","triceps":"S8","stretching":"S4","back":"S3","forearms_(front)":"S4"}},{"id":"dumbbell_chest_press_flat","name":"dumbbell_chest_press_flat","description":"A fundamental exercise for chest development that allows a more natural movement than a barbell. Using dumbbells increases the range of motion and activates more stabilizing muscles in the shoulder girdle.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Shoulders (Front)"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S6","chest":"P10","triceps":"S8","glutes":"T2","stretching":"S4","back":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_chest_press_incline_bench","name":"dumbbell_chest_press_incline_bench","description":"A key exercise for shaping the upper chest muscles and a fuller chest appearance. The positive incline redirects stress to the clavicular portion of the chest and the front shoulder.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":["Shoulders (Front)","Triceps"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S7","chest":"P10","triceps":"S8","stretching":"S4","back":"S3","forearms_(front)":"S4"}},{"id":"dumbbell_chest_pull_over","name":"dumbbell_chest_pull_over","description":"A unique exercise that simultaneously stretches and strengthens the chest muscles and the latissimus dorsi. Great for broadening the chest and improving shoulder mobility.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":["Back","Triceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S5","chest":"P8","triceps":"S6","glutes":"T2","stretching":"P8","back":"P8","biceps":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_cross_body_hammer_curl","name":"dumbbell_cross_body_hammer_curl","description":"A hammer curl variation targeting the brachialis and brachioradialis, giving the arms a 'thicker' look. The cross-body movement changes the angle of load and relieves the wrists.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":["Forearms (Front)","Brachialis"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S2","biceps":"P10","forearms_(front)":"S8"}},{"id":"dumbbell_cuban_press","name":"dumbbell_cuban_press","description":"A top exercise for shoulder health and rotator cuff strength. Combines an upright row, external rotation, and press, which is crucial for athletic performance and injury prevention.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Back (Upper)","Rotator Cuff","Triceps"],"muscle_intensity":{"other":"P6","abs_/_core":"S4","shoulders":"P10","triceps":"S6","stretching":"S4","back":"S7","biceps":"S4","forearms_(front)":"S5"}},{"id":"dumbbell_curl_press_extend","name":"dumbbell_curl_press_extend","description":"The ultimate full-arm combination: bicep curl, shoulder press, and tricep extension. This exercise maximizes time under tension for all major arm muscle groups.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":["Triceps","Shoulders","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S8","triceps":"P9","back":"S4","biceps":"P9","cardio":"S4","forearms_(front)":"S5"}},{"id":"dumbbell_curls","name":"dumbbell_curls","description":"A classic for bicep building that never disappoints. Using dumbbells allows wrist supination, which is key for full bicep contraction.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":["Forearms (Front)","Brachialis"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S2","biceps":"P10","forearms_(front)":"S6"}},{"id":"dumbbell_curls_alternating","name":"dumbbell_curls_alternating","description":"Alternating execution allows better concentration on each muscle individually. Since one arm rests briefly, you can often use slightly heavier dumbbells.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":["Forearms (Front)","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S2","biceps":"P10","forearms_(front)":"S6"}},{"id":"dumbbell_decline_bench_press","name":"dumbbell_decline_bench_press","description":"A powerful press at a negative angle that reduces shoulder load and redirects it directly to the chest muscles. Ideal for those who have shoulder problems with the classic bench press.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Shoulders (Front)"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S5","chest":"P10","triceps":"S8","stretching":"S4","back":"S3","forearms_(front)":"S4"}},{"id":"dumbbell_decline_triceps_pull_over_extension","name":"dumbbell_decline_triceps_pull-over_extension","description":"A hybrid exercise combining a pullover and a skull crusher. The decline angle increases the stretch on the long head of the tricep, leading to exceptional growth and definition.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":["Back","Chest","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S4","chest":"S4","triceps":"P10","glutes":"T2","stretching":"S5","back":"P8","biceps":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_elbow_side_plank","name":"dumbbell_elbow_side_plank","description":"An isometric core challenge upgraded with additional dumbbell weight. This exercise builds unbreakable core stability and strong hips, essential for every athlete.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Abs / Core","secondary_muscles":["Obliques","Shoulders","Glutes"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S7","calves":"T2","glutes":"S6","back":"S5","cardio":"S3","forearms_(front)":"S4"}},{"id":"dumbbell_farmer_walks","name":"dumbbell_farmer_walks","description":"One of the most functional exercises in the world. Walking with heavy weights develops brutal grip strength, strong forearms, a stable core, and full-body endurance.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Forearms (Front)","secondary_muscles":["Abs / Core","Back","Cardio","Legs"],"muscle_intensity":{"other":"P7","abs_/_core":"S8","shoulders":"S6","calves":"S5","legs_quads":"S6","glutes":"S6","legs_hamstrings":"S5","back":"S8","biceps":"S4","cardio":"P8","forearms_(front)":"P10"}},{"id":"dumbbell_front_raise","name":"dumbbell_front_raise","description":"An isolation exercise for the front deltoids. Helps create a '3D' shoulder appearance and improves upper body stability in pressing movements.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Chest (Upper)","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"P10","chest":"S4","triceps":"S3","back":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_front_squat","name":"dumbbell_front_squat","description":"A front-loaded squat that heavily loads the quads and upper back. Due to the forward center of gravity, it promotes a more upright posture and is safe for the lower back.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Legs – Quads","secondary_muscles":["Abs / Core","Glutes","Back"],"muscle_intensity":{"abs_/_core":"S7","shoulders":"S5","calves":"S4","legs_quads":"P10","glutes":"S8","legs_hamstrings":"S6","back":"S6","biceps":"S4","cardio":"S5","forearms_(front)":"S4"}},{"id":"dumbbell_goblet_2_sec_hold_squat","name":"dumbbell_goblet_2_sec_hold_squat","description":"The pause method eliminates elastic energy and forces the muscles into maximum work at the push-off. An excellent exercise for improving hip mobility and strength at the bottom of the squat.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Abs / Core","Hamstrings"],"muscle_intensity":{"abs_/_core":"S7","shoulders":"S4","calves":"S4","legs_quads":"P10","glutes":"S9","legs_hamstrings":"S7","stretching":"S5","back":"S5","biceps":"S4","cardio":"S6","forearms_(front)":"S4"}},{"id":"dumbbell_goblet_forward_lunge","name":"dumbbell_goblet_forward_lunge","description":"A dynamic exercise combining the strength of a lunge with the stability of the goblet grip. Excellently targets the quads and glutes while also raising the heart rate.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Hamstrings","Cardio"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S4","calves":"S5","legs_quads":"P10","glutes":"S9","legs_hamstrings":"S7","stretching":"S4","back":"S4","biceps":"S4","cardio":"P8","forearms_(front)":"S4"}},{"id":"dumbbell_half_biceps_curl_for_21s","name":"dumbbell_half_biceps_curl_for_21s","description":"The popular '21s' method with dumbbells that maximizes time under tension. The exercise is divided into three phases: 7 reps in the bottom half, 7 in the top half, and 7 full reps, causing exceptional metabolic stress in the biceps.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":["Forearms (Front)"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S2","stretching":"S3","biceps":"P10","forearms_(front)":"S6"}},{"id":"dumbbell_half_kneeling_military_press","name":"dumbbell_half_kneeling_military_press","description":"The overhead press in a half-kneeling position is one of the best exercises for core stabilization. By removing the ability to use your legs for assistance, all the load transfers to the shoulders and abdominal muscles.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Abs / Core","Triceps","Glutes"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"P10","chest":"S3","triceps":"S7","glutes":"S6","stretching":"S4","back":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_hammer_curl","name":"dumbbell_hammer_curl","description":"Hammer curls with a neutral grip powerfully activate the brachioradialis and brachialis. A key exercise for developing arm thickness and forearm strength.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":["Forearms (Front)","Brachialis"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S2","biceps":"P10","forearms_(front)":"S8"}},{"id":"dumbbell_hammer_strict_curl","name":"dumbbell_hammer_strict_curl","description":"A hammer curl performed in strict form with no body sway. The neutral grip targets the brachialis and brachioradialis for thick, dense arm development.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_hand_side_plank","name":"dumbbell_hand_side_plank","description":"The palm side plank with a dumbbell adds an element of dynamic or static load to the core stabilizers. Increases oblique muscle strength and shoulder joint stability.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Abs / Core","secondary_muscles":["Obliques","Shoulders"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S8","calves":"T2","triceps":"S4","glutes":"S5","back":"S5","cardio":"S3","forearms_(front)":"S5"}},{"id":"dumbbell_hang_power_clean","name":"dumbbell_hang_power_clean","description":"An explosive dumbbell movement pulling from a hanging position to a rack catch. It develops total-body power and coordination, mimicking the benefits of Olympic lifting with dumbbells.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"dumbbell_high_curl","name":"dumbbell_high_curl","description":"A bicep curl that continues past the standard endpoint, bringing the weights toward the shoulders. This extended range of motion increases the peak contraction of the biceps.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_hip_thrust","name":"dumbbell_hip_thrust","description":"The hip thrust with a dumbbell is one of the most effective glute isolation exercises. The horizontal nature of the load allows maximum glute activation without excessive spinal stress.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Glutes","secondary_muscles":["Hamstrings","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","calves":"S3","legs_quads":"S5","glutes":"P10","legs_hamstrings":"S8","stretching":"S4","back":"S4","cardio":"S3"}},{"id":"dumbbell_incline_alternate_bicep_curl","name":"dumbbell_incline_alternate_bicep_curl","description":"An alternating bicep curl performed on an incline bench. The incline position stretches the long head of the bicep at the bottom, leading to a greater range of motion and superior development.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_incline_alternate_curl","name":"dumbbell_incline_alternate_curl","description":"An alternating dumbbell curl on an incline bench with a neutral or standard grip. The inclined position maximizes the bicep stretch and promotes balanced arm development.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_incline_alternate_hammer_curl","name":"dumbbell_incline_alternate_hammer_curl","description":"An alternating hammer curl performed on an incline bench. The combination of a neutral grip and incline angle powerfully targets the long head of the bicep and brachialis.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_incline_breeding","name":"dumbbell_incline_breeding","description":"A dumbbell fly (chest opening) performed on an incline bench to target the upper chest. The wide arc of movement maximally stretches and contracts the upper pectoral fibers.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"dumbbell_incline_triceps_extension","name":"dumbbell_incline_triceps_extension","description":"A skull crusher variation performed on an incline bench. The incline angle places a unique stretch on the long head of the triceps for comprehensive arm development.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","triceps":"P8"}},{"id":"dumbbell_incline_twisted_fly","name":"dumbbell_incline_twisted_fly","description":"An incline chest fly with a rotation of the wrists during the movement. The twist adds a rotational element that recruits more muscle fibers across the chest.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2","chest":"P8","triceps":"S5"}},{"id":"dumbbell_kickback","name":"dumbbell_kickback","description":"An isolation exercise for the triceps that focuses on complete arm extension. Due to the gravitational angle, the load is greatest precisely at the moment of maximum muscle contraction.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":["Shoulders (Rear)"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S4","triceps":"P10","back":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_kneeling_arnold_press","name":"dumbbell_kneeling_arnold_press","description":"The Arnold Press performed in a kneeling position. Removing the lower body from the equation isolates the shoulders and forces the core to stabilize the movement.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":[],"muscle_intensity":{"shoulders":"P8","triceps":"S3"}},{"id":"dumbbell_kneeling_hold_to_stand_clean_grip","name":"dumbbell_kneeling_hold_to_stand_clean_grip","description":"A movement from a kneeling position to standing while holding dumbbells in a clean grip. It builds functional leg strength, hip drive, and total-body coordination.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"dumbbell_lunge_pulse","name":"dumbbell_lunge_pulse","description":"Pulsing lunges keep the muscles under constant tension since you never return to a fully standing position. This increases metabolic stress in the quads and glutes.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Hamstrings","Cardio"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S3","calves":"S5","legs_quads":"P10","glutes":"S8","legs_hamstrings":"S6","stretching":"S4","back":"S4","cardio":"P7","forearms_(front)":"S4"}},{"id":"dumbbell_offset_squat","name":"dumbbell_offset_squat","description":"A squat with a dumbbell held on one side only. The asymmetric loading creates a lateral challenge for the core stabilizers and introduces a unilateral demand on the legs.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"dumbbell_one_arm_floor_fly","name":"dumbbell_one_arm_floor_fly","description":"A chest fly performed lying on the floor with one dumbbell. The floor limits the range of motion at the bottom, reducing shoulder strain while still targeting the pectoral muscles.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"dumbbell_one_arm_floor_press","name":"dumbbell_one_arm_floor_press","description":"A single-arm chest press performed lying on the floor. The floor limits the range of motion and the unilateral load demands greater core anti-rotation stability.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"dumbbell_one_arm_front_raise","name":"dumbbell_one_arm_front_raise","description":"The one-arm front raise allows complete isolation of the front deltoid and correction of asymmetries. Since only one arm is working, the core must work harder to prevent trunk rotation.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Abs / Core","Chest (Upper)"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"P10","chest":"S4","triceps":"S4","back":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_one_arm_hammer_preacher_curl","name":"dumbbell_one_arm_hammer_preacher_curl","description":"An isolation exercise on a preacher bench that, with a neutral hammer grip, shifts the emphasis to the brachialis and brachioradialis. The preacher bench prevents momentum use, ensuring strict muscle loading.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":["Forearms (Front)","Brachialis"],"muscle_intensity":{"abs_/_core":"S2","stretching":"S4","biceps":"P10","forearms_(front)":"S7"}},{"id":"dumbbell_one_arm_triceps_extension_on_bench","name":"dumbbell_one_arm_triceps_extension_(on_bench)","description":"One of the best exercises for isolating the long head of the tricep. Performing on a bench provides greater body stability, allowing full focus on contracting and stretching the back of the arm.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":["Shoulders","Chest"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S4","chest":"S3","triceps":"P10","stretching":"S5","forearms_(front)":"S4"}},{"id":"dumbbell_one_arm_wrist_curl","name":"dumbbell_one_arm_wrist_curl","description":"A wrist curl performed with a single dumbbell to address forearm strength asymmetries. Full concentration on one wrist at a time allows greater mind-muscle connection.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_overhead_sit_up","name":"dumbbell_overhead_sit-up","description":"An advanced trunk curl where the overhead weight dramatically increases the lever arm and demand for core and shoulder stabilization. The exercise builds functional strength in the entire anterior body.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Back","Triceps"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S6","calves":"T2","triceps":"S4","legs_quads":"S3","back":"S5","cardio":"S3","forearms_(front)":"S4"}},{"id":"dumbbell_plank_pullthrough","name":"dumbbell_plank_pullthrough","description":"An exceptional exercise for anti-rotational core stability. Pulling the weight under the body in a plank position forces the abdominal muscles and back to work maximally to keep the hips aligned.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Abs / Core","secondary_muscles":["Back","Shoulders","Glutes"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S7","calves":"T2","triceps":"S4","glutes":"S4","back":"P8","biceps":"S4","cardio":"S4","forearms_(front)":"S5"}},{"id":"dumbbell_press_squat","name":"dumbbell_press_squat","description":"A compound exercise combining a squat with an overhead press at the top. It trains the entire body efficiently, linking lower-body power with upper-body pushing strength.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"dumbbell_pullover","name":"dumbbell_pullover","description":"A classic exercise that bridges the gap between chest and back training. The emphasis is on stretching the chest muscles and strong contraction of the latissimus dorsi and serratus anterior.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":["Chest","Triceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S4","chest":"P8","triceps":"S6","glutes":"T2","stretching":"P8","back":"P9","biceps":"S4","forearms_(front)":"S4"}},{"id":"dumbbell_seated_curl","name":"dumbbell_seated_curl","description":"A bicep curl performed seated to eliminate any lower-body momentum. Strict seated form maximally isolates the biceps for targeted hypertrophy.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_shrugs","name":"dumbbell_shrugs","description":"An isolation exercise for the upper trapezius using dumbbells. The neutral grip of dumbbells allows a more natural wrist position and a greater range of motion compared to a barbell.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"dumbbell_simultaneous_biceps_curl","name":"dumbbell_simultaneous_biceps_curl","description":"A bicep curl where both arms curl at the same time. Simultaneous execution maintains constant bilateral tension and builds overall bicep mass efficiently.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"dumbbell_split_squat","name":"dumbbell_split_squat","description":"A stationary split squat holding dumbbells at the sides. It develops unilateral leg strength, balance, and hip flexibility in a stable, controlled position.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"dumbbell_squats","name":"dumbbell_squats","description":"A squat with dumbbells held at the sides. The neutral position of the weights is comfortable and accessible, making it a great introduction to loaded squatting.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"dumbbell_straight_leg_russian_twist","name":"dumbbell_straight_leg_russian_twist","description":"A Russian twist with the legs held straight out, increasing the lever arm and the demand on the hip flexors and core. The added dumbbell increases rotational strength.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"dumbbell_suitcase_carry","name":"dumbbell_suitcase_carry","description":"A unilateral walking exercise simulating carrying a heavy suitcase. This is the queen of asymmetric loading, building incredible strength in the oblique abdominal muscles and spinal stabilizers.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Abs / Core","secondary_muscles":["Back","Forearms (Front)","Cardio","Legs"],"muscle_intensity":{"other":"P7","abs_/_core":"P10","shoulders":"S6","calves":"S5","legs_quads":"S6","glutes":"S6","legs_hamstrings":"S5","back":"S8","biceps":"S4","cardio":"P7","forearms_(front)":"P9"}},{"id":"dumbbell_swing","name":"dumbbell_swing","description":"A hip-hinge swinging movement with a dumbbell, similar to a kettlebell swing. It develops explosive hip extension, posterior chain power, and cardiovascular conditioning.","difficulty":2,"category":"strength","equipment":["weights"],"primary_muscle":"Stretching","secondary_muscles":[],"muscle_intensity":{"stretching":"P7"}},{"id":"dumbbell_tate_press","name":"dumbbell_tate_press","description":"A tricep exercise where the dumbbells are lowered to the chest in a wide arc and then pressed back up. It uniquely targets all three heads of the tricep with a strong focus on the medial head.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"dumbbell_w_press","name":"dumbbell_w_press","description":"A shoulder press variation where the elbows track in a W shape throughout the movement. It targets the rear deltoids and external rotators more than a standard press.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"elbow_push_plank_up","name":"elbow_push_plank_up","description":"A dynamic plank exercise transitioning between a forearm plank and a full push-up plank one arm at a time. It builds shoulder and tricep strength while maintaining core stability.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"elevated_push_up","name":"elevated_push_up","description":"A push-up with the hands on an elevated surface such as a bench. The elevated position reduces the load relative to a standard push-up, making it more accessible for beginners.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"explosive_push_ups","name":"explosive_push_ups","description":"A plyometric exercise for the upper body that builds explosive chest and tricep strength. Essential for athletes who need fast and powerful pushing or striking.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Shoulders","Abs / Core"],"muscle_intensity":{"abs_/_core":"S7","shoulders":"S6","chest":"P10","triceps":"S8","stretching":"S4","back":"S4","cardio":"P7","forearms_(front)":"S5"}},{"id":"fire_hydrant_bodyweight","name":"fire_hydrant_bodyweight","description":"A quadruped exercise raising the bent leg out to the side like a dog at a fire hydrant. It isolates the gluteus medius for hip abduction strength and pelvic stability.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"frog_jumps","name":"frog_jumps","description":"A dynamic plyometric exercise that raises the heart rate and builds lower body explosiveness. Due to the wide foot placement, it additionally activates the adductors and glutes.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Cardio","Calves","Hamstrings"],"muscle_intensity":{"other":"P8","abs_/_core":"S6","calves":"S7","legs_quads":"P10","glutes":"S9","legs_hamstrings":"S7","stretching":"S5","back":"S5","cardio":"P9"}},{"id":"front_lever_raise","name":"front_lever_raise","description":"An extremely demanding gymnastics-type exercise requiring top-level strength in the entire posterior chain and core. The lats, shoulders, and abdominal muscles are most loaded during the front lever.","difficulty":9,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":["Abs / Core","Shoulders","Glutes"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S8","chest":"S4","triceps":"S5","legs_quads":"S4","glutes":"S7","legs_hamstrings":"S6","back":"P10","biceps":"S5","cardio":"S3","forearms_(front)":"S8"}},{"id":"front_raises_barbell","name":"front_raises_barbell","description":"A barbell exercise for isolating the front deltoids. Unlike dumbbells, the barbell requires better synchronization of both arms and core stability, as the center of gravity is more fixed.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Abs / Core","Chest (Upper)"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"P10","chest":"S5","triceps":"S3","glutes":"S4","back":"S5","forearms_(front)":"S5"}},{"id":"front_squats_dumbbell_low","name":"front_squats_dumbbell_low","description":"A squat with dumbbells held low in front that forces the torso into a more upright position, greatly increasing quad and core stabilizer activation.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Abs / Core","Back"],"muscle_intensity":{"abs_/_core":"S7","shoulders":"S4","calves":"S4","legs_quads":"P10","glutes":"S8","legs_hamstrings":"S6","stretching":"S4","back":"S6","biceps":"S4","cardio":"S5","forearms_(front)":"S5"}},{"id":"full_planche_push_up","name":"full_planche_push_up","description":"One of the most demanding bodyweight exercises. Push-ups in a horizontal floating position require incredible shoulder, chest, and core strength, with extreme pressure on the shoulders due to the long lever.","difficulty":10,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Shoulders","secondary_muscles":["Chest","Triceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"P10","chest":"P10","triceps":"S9","legs_quads":"S5","glutes":"S7","legs_hamstrings":"S5","back":"S7","biceps":"S4","cardio":"S4","forearms_(front)":"S8"}},{"id":"gym_elliptical_machine_normal_speed","name":"gym_elliptical_machine_normal_speed","description":"A low-impact cardio exercise on the elliptical trainer that mimics running without the joint impact. It improves cardiovascular endurance and engages both the upper and lower body simultaneously.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"gym_rowing_machine_normal_speed","name":"gym_rowing_machine_normal_speed","description":"Rowing machine training is an excellent compound exercise engaging almost all muscle groups. At normal speed it builds strength endurance and improves cardiovascular fitness, with an emphasis on the back's pulling muscles.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":["Cardio","Legs","Biceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S5","calves":"S4","legs_quads":"S7","glutes":"S6","legs_hamstrings":"S7","stretching":"S3","back":"P10","biceps":"S6","cardio":"P9","forearms_(front)":"S6"}},{"id":"hack_squat_machine","name":"hack_squat_machine","description":"A squat performed on a hack squat machine with the back supported at an angle. It targets the quadriceps intensely while the machine guides the movement for safety.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"half_burpees","name":"half_burpees","description":"A burpee variation that omits the jump at the top, making it lower impact. It still builds total-body strength and elevates the heart rate, but is gentler on the joints.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"half_lotus","name":"half_lotus","description":"A seated yoga-inspired stretch bringing one foot to rest on the opposite thigh. It improves hip external rotation, flexibility, and prepares the body for deeper mobility work.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"hanging_knee_raises","name":"hanging_knee_raises","description":"A hanging exercise where the knees are pulled toward the chest. It targets the lower abdominal muscles and hip flexors while also building grip strength.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"hanging_leg_raises","name":"hanging_leg_raises","description":"Hanging leg raises are one of the most effective exercises for the lower abdominal muscles. They also require a strong grip and shoulder stability to prevent body swinging.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Forearms (Front)","Shoulders"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S6","calves":"T2","legs_quads":"S5","legs_hamstrings":"S3","stretching":"S4","back":"S4","biceps":"S4","cardio":"S3","forearms_(front)":"S7"}},{"id":"hanging_oblique_crunches","name":"hanging_oblique_crunches","description":"A hanging exercise where the knees are pulled diagonally toward one elbow at a time. It powerfully targets the oblique muscles while building grip strength and core endurance.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs  /  Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S3","calves":"T2"}},{"id":"headstand","name":"headstand","description":"An inverted gymnastics hold balancing on the top of the head with the body vertical. It develops shoulder and core strength, improves balance, and builds body awareness.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"heel_touches","name":"heel_touches","description":"A lying abdominal exercise reaching alternately toward each heel. It targets the obliques and upper abs with a simple, controlled side-to-side movement.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"hollow_hold","name":"hollow_hold","description":"A fundamental core stability exercise used in gymnastics. Key for learning the neutral spine position under load and preventing anterior pelvic tilt.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Legs – Quads"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S4","calves":"T2","legs_quads":"S4","glutes":"S3","back":"S3"}},{"id":"inverted_rows_on_smith_machine","name":"inverted_rows_on_smith_machine","description":"A horizontal pulling exercise with the body underneath a Smith machine bar. It trains the upper back, biceps, and rear deltoids in a row pattern, and the difficulty adjusts with body angle.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"jogging","name":"jogging","description":"A moderate-pace running exercise that improves cardiovascular fitness and burns calories. It is gentler on the joints than sprinting and suitable for sustained aerobic conditioning.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"jump_rope_alternating_foot","name":"jump_rope_alternating_foot","description":"A jump rope technique alternating which foot lands with each rope rotation. It improves coordination, footwork, and cardiovascular endurance with a rhythmic, low-impact pattern.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"jump_rope_basic_jump","name":"jump_rope_basic_jump","description":"Basic jump rope is a top exercise for coordination, endurance, and calf strengthening. Great as a warm-up or as an intense cardio insert.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":["Calves","Shoulders","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S5","calves":"P10","triceps":"S3","legs_quads":"S6","glutes":"S5","legs_hamstrings":"S4","back":"S4","cardio":"P10","forearms_(front)":"S6"}},{"id":"jump_rope_double_bounce","name":"jump_rope_double_bounce","description":"A jump rope variation taking two small hops per rope rotation. The double bounce slows the rhythm and is ideal for beginners learning timing and coordination.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"jump_rope_face_pull","name":"jump_rope_face_pull","description":"A creative combination movement simulating a face pull motion with resistance bands while performing jumping jacks or other cardio. It builds shoulder health and cardio simultaneously.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"jump_rope_row","name":"jump_rope_row","description":"A rowing movement performed with a jump rope as resistance. It targets the upper back and biceps while the rope provides accommodating resistance through the pulling range.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"jump_squats_bodyweight","name":"jump_squats_bodyweight","description":"An explosive plyometric exercise combining squat strength with a vertical jump. The primary load is on the quads, while the cardiovascular system works at high intensity.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Cardio","Glutes","Calves"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S3","calves":"S8","legs_quads":"P10","glutes":"S8","legs_hamstrings":"S6","stretching":"S4","back":"S5","cardio":"P9"}},{"id":"jumping_jack","name":"jumping_jack","description":"A classic aerobic exercise for full-body warm-up. Improves coordination and rhythmic endurance while also activating the shoulder girdle and calves.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":["Calves","Shoulders"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S6","calves":"S8","legs_quads":"S5","glutes":"S5","legs_hamstrings":"S4","stretching":"S3","back":"S4","cardio":"P10"}},{"id":"jumping_lunge","name":"jumping_lunge","description":"An explosive lunge variation where you jump and switch legs mid-air. It builds lower body power, cardiovascular fitness, and unilateral leg strength simultaneously.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"jumping_pistol_squat","name":"jumping_pistol_squat","description":"An explosive single-leg squat with a jump at the top. It demands exceptional strength, balance, and power from the quads, glutes, and calves of a single leg.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"kettlebell_alternating_renegade_row","name":"kettlebell_alternating_renegade_row","description":"A complex exercise combining plank stability with single-arm rowing. Requires exceptional core strength to prevent hip rotation when lifting the kettlebell.","difficulty":7,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":["Abs / Core","Shoulders","Forearms (Front)"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S8","calves":"T2","chest":"S4","triceps":"S5","glutes":"S6","back":"P9","biceps":"S6","cardio":"S5","forearms_(front)":"S7"}},{"id":"kettlebell_bulgarian_split_squat_right","name":"kettlebell_bulgarian_split_squat_right","description":"A Bulgarian split squat holding a kettlebell with the right leg forward. The kettlebell adds load while the elevated rear foot maximizes the stretch and activation of the working leg.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"kettlebell_calf_raise","name":"kettlebell_calf_raise","description":"A calf raise holding a kettlebell for added resistance. The extra load increases the strength demand on the gastrocnemius and soleus for greater calf development.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"kettlebell_concentration_curl","name":"kettlebell_concentration_curl","description":"A bicep curl with a kettlebell performed with the elbow braced against the inner thigh. Full isolation of the bicep eliminates any body movement for a strict, focused contraction.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"kettlebell_curl","name":"kettlebell_curl","description":"A standard bicep curl performed with a kettlebell. The offset center of gravity of the kettlebell adds a unique rotational challenge to the wrist and forearm.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Biceps","secondary_muscles":[],"muscle_intensity":{"biceps":"P9","forearms_(front)":"S4"}},{"id":"kettlebell_front_raise","name":"kettlebell_front_raise","description":"A front deltoid raise performed with a kettlebell. The handle position of the kettlebell allows a natural wrist rotation during the lift for a slightly different stimulus than dumbbells.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Shoulders","secondary_muscles":[],"muscle_intensity":{"shoulders":"P8","triceps":"S3"}},{"id":"kettlebell_glute_bridge","name":"kettlebell_glute_bridge","description":"A glute bridge performed with a kettlebell placed on the hips. The added weight increases the load on the glutes and hamstrings for greater strength and hypertrophy.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":[],"muscle_intensity":{"other":"P5"}},{"id":"kettlebell_gorilla_row","name":"kettlebell_gorilla_row","description":"A bilateral kettlebell row performed in a wide stance with two kettlebells on the floor. You alternate rowing each kettlebell while the other rests, combining back strength with core anti-rotation stability.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"kettlebell_pullover","name":"kettlebell_pullover","description":"A pullover movement performed with a kettlebell, lying on a bench or the floor. It stretches and strengthens the chest, lats, and serratus anterior through a long arc of motion.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"kettlebell_row","name":"kettlebell_row","description":"A single-arm or bilateral row with a kettlebell targeting the latissimus dorsi, rhomboids, and biceps. The kettlebell's offset handle provides a unique grip challenge compared to dumbbells.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"kettlebell_split_squat","name":"kettlebell_split_squat","description":"A stationary split squat holding a kettlebell. The offset weight distribution of the kettlebell adds a stability challenge to the wrists and core during the movement.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"kettlebell_squats","name":"kettlebell_squats","description":"A squat holding one or two kettlebells, typically in a goblet or racked position. The weight placement encourages an upright torso and deep squat depth.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"kettlebell_sumo_deadlift","name":"kettlebell_sumo_deadlift","description":"A wide-stance deadlift with a kettlebell. The sumo position targets the inner thighs and glutes more than a conventional stance and allows a more upright torso.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"kettlebell_sumo_squat","name":"kettlebell_sumo_squat","description":"A sumo-stance squat holding a kettlebell between the legs. The wide stance and external hip rotation place greater emphasis on the inner thighs and glutes.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Quadriceps","secondary_muscles":[],"muscle_intensity":{"legs_quads":"P8","glutes":"S6","legs_hamstrings":"S3"}},{"id":"kettlebell_swing","name":"kettlebell_swing","description":"The foundational kettlebell exercise using explosive hip hinging to swing the bell from between the legs to chest height. It develops posterior chain power, cardiovascular fitness, and grip strength.","difficulty":2,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Stretching","secondary_muscles":[],"muscle_intensity":{"stretching":"P7"}},{"id":"kipping_handstand_push_up","name":"kipping_handstand_push-up","description":"A handstand push-up using a kipping momentum assist from the legs to help complete the pressing motion. It allows higher volume overhead pressing and is used in CrossFit for shoulder and tricep development.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":[],"muscle_intensity":{"shoulders":"S3","chest":"P8","triceps":"S5"}},{"id":"kipping_pull_up","name":"kipping_pull_up","description":"A pull-up using a dynamic kipping motion to generate momentum and assist the pull. It allows higher repetition output and is a core movement in CrossFit, training the back and biceps.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":[],"muscle_intensity":{"glutes":"T2","back":"P8","biceps":"S4"}},{"id":"l_sit_hold","name":"l_sit_hold","description":"An isometric exercise requiring enormous abdominal, hip flexor, and tricep strength to hold the body above the ground. It is the foundation for advanced gymnastics elements.","difficulty":8,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Triceps","Legs – Quads","Shoulders"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S7","chest":"S4","triceps":"S8","legs_quads":"S8","stretching":"S5","back":"S5","forearms_(front)":"S6"}},{"id":"leg_raises_straight_legs","name":"leg_raises_(straight_legs)","description":"Straight-leg raises lying down are one of the best isolation exercises for the lower abdominal muscles. Key is controlling the lowering phase for maximum tension.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Legs – Quads"],"muscle_intensity":{"abs_/_core":"P10","legs_quads":"S6","legs_hamstrings":"S3","stretching":"S4","back":"S4"}},{"id":"lying_leg_raise","name":"lying_leg_raise","description":"The lying leg raise is a classic exercise for strengthening the lower abdominal muscles and core stabilization. Lying on your back, you raise your legs in a controlled manner, requiring strong core activation. Perfect for a sculpted abdomen and better posture.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Hip Flexors","Legs – Quads"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"T2","legs_quads":"S4"}},{"id":"middle_crunches","name":"middle_crunches","description":"A basic trunk curl that focuses on the upper and middle portion of the rectus abdominis. The exercise is safe, effective, and suitable for all fitness levels. The key to success is a short but intense muscle squeeze.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P8"}},{"id":"military_press_bodyweight","name":"military_press_bodyweight","description":"The overhead press with bodyweight is a great exercise for the shoulder girdle and triceps. By raising the hips into an inverted V shape, you simulate a vertical press. It improves upper body strength and shoulder stability.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Shoulders","secondary_muscles":["Triceps","Chest","Abs / Core"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"P9","chest":"S4","triceps":"P7"}},{"id":"modified_hindu_push_up","name":"modified_hindu_push_up","description":"A dynamic and fluid exercise combining strength, mobility, and flexibility. The movement mimics 'diving' under a low obstacle, powerfully activating the chest, shoulders, and spine. Great for developing athletic strength.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Shoulders","Triceps","Back"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"P8","chest":"P8","triceps":"S6","stretching":"T4","back":"S3"}},{"id":"mountain_climbers","name":"mountain_climbers","description":"Mountain climbers are an explosive exercise that raises heart rate and burns fat. In a plank position, you alternately pull your knees toward your chest, simulating a fast uphill run. Ideal for metabolic training and a strong core.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":["Abs / Core","Shoulders","Legs – Quads"],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S5","triceps":"S3","legs_quads":"S6","cardio":"P9"}},{"id":"multi_hip_abduction","name":"multi_hip_abduction","description":"Hip abduction is a key exercise for strengthening the smaller glute muscles and pelvic stability. Helps shape the sides of the hips and prevents knee pain. Can be performed standing or lying down.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Glutes","secondary_muscles":["Abs / Core"],"muscle_intensity":{"other":"P8","abs_/_core":"S3","glutes":"P8"}},{"id":"multi_hip_adduction","name":"multi_hip_adduction","description":"Hip adduction targets the inner thigh muscles (adductors), which are often neglected. The exercise improves leg strength balance and stabilizes the pelvis. Great for toning the thighs.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Other","secondary_muscles":["Abs / Core"],"muscle_intensity":{"other":"P8","abs_/_core":"S3"}},{"id":"normal_push_up","name":"normal_push-up","description":"The push-up is the gold standard for upper body strength. It strengthens the chest, shoulders, triceps, and stabilizes the entire core in one movement. A versatile exercise you can do anywhere.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Triceps","Shoulders","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S5","chest":"P9","triceps":"S7"}},{"id":"oblique_crunch","name":"oblique_crunch","description":"An exercise for the lateral abdominal muscles that helps shape the waist and rotational strength. By rotating the trunk, you activate the oblique muscles, which improves core stability. A simple yet effective way to a functional abdomen.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":[],"muscle_intensity":{"abs_/_core":"P9"}},{"id":"one_arm_reverse_dumbbell_fly","name":"one_arm_reverse_dumbbell_fly","description":"The one-arm reverse dumbbell fly in a bent-over position isolates the rear deltoids and upper back. An excellent exercise for improving posture and balanced shoulder development. Unilateral execution also provides additional core stability.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Back","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"P9","back":"S7"}},{"id":"overhead_extension_resistance_band_both_arms","name":"overhead_extension_resistance_band_both_arms","description":"The overhead tricep extension allows maximum stretch of the long head of the tricep. Using a resistance band ensures constant tension throughout the full range of motion. Ideal for firm and defined arms.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":["Shoulders","Abs / Core"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S4","triceps":"P10"}},{"id":"pike_push_up","name":"pike_push_up","description":"The pike push-up is an advanced push-up variation that shifts the weight onto the shoulders. By raising the hips, you create an angle that simulates an overhead press. A key exercise for those who want strong and wide shoulders.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Shoulders","secondary_muscles":["Triceps","Chest"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"P9","chest":"S4","triceps":"S7","stretching":"T3"}},{"id":"plank_cross_knee_drive","name":"plank_cross_knee_drive","description":"A dynamic plank with diagonal knee drives powerfully activates the oblique abdominal muscles. The exercise improves core stability while also raising the heart rate. Great for developing functional core strength.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Cardio"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S5","triceps":"S4","legs_quads":"S3","cardio":"S5"}},{"id":"plank_jack","name":"plank_jack","description":"Plank jacks combine the stability of a plank with the explosiveness of jumps. By spreading and closing the legs in a plank position, you heavily load the core and lower body. An excellent choice for burning calories.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":["Abs / Core","Glutes","Shoulders"],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S6","calves":"S3","legs_quads":"S4","glutes":"S5","cardio":"P8"}},{"id":"plank_knee_tucks","name":"plank_knee_tucks","description":"Knee tucks in a plank are an intense exercise for the lower abdomen and shoulder stabilizers. Controlled knee movements toward the chest increase tension in the core. Helps improve coordination and core strength.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Legs – Quads"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S5","legs_quads":"S4","cardio":"S5"}},{"id":"plank_lunges","name":"plank_lunges","description":"Plank lunges are a hybrid exercise combining upper body stability with leg strength and hip mobility. Stepping a foot next to the hand opens the hips and powerfully activates the legs. Great for agility and hip opening.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Abs / Core","Glutes","Shoulders"],"muscle_intensity":{"abs_/_core":"P8","shoulders":"S5","calves":"T2","legs_quads":"P9","glutes":"S7","legs_hamstrings":"S5","stretching":"T4","cardio":"S6"}},{"id":"plank_on_elbows","name":"plank_on_elbows","description":"The classic elbow plank is the foundation of every core workout. Maintaining a straight body line strengthens the deep abdominal muscles and spinal stabilizers. Simple but brutally effective for muscular endurance.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Back","Glutes"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S6","legs_quads":"S4","glutes":"S5","back":"S5"}},{"id":"plank_reach_through","name":"plank_reach_through","description":"The reach-through plank adds an element of rotation and single-arm stabilization. It powerfully targets the oblique abdominal muscles and increases thoracic spine mobility. A challenge for your balance and shoulder strength.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Back"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S7","triceps":"S4","stretching":"T3","back":"S6"}},{"id":"plank_shoulder_taps","name":"plank_shoulder_taps","description":"Shoulder taps in a plank are a top exercise for anti-rotational core strength. When you lift one hand, the core must prevent hip rotation, activating the stabilizers. Strengthens the shoulders and teaches full-body control.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Triceps"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S8","triceps":"S5","legs_quads":"S3","glutes":"S4","cardio":"S4"}},{"id":"plate_front_raise","name":"plate_front_raise","description":"The plate front raise is an isolation exercise for the front deltoids. The movement is controlled and goes to eye level, providing a constant burning sensation in the shoulders. Great for finishing a shoulder workout.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Chest","Abs / Core","Forearms (Front)"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"P9","chest":"S4","back":"S3","forearms_(front)":"S4"}},{"id":"pull_up_normal_grip","name":"pull_up_normal_grip","description":"The standard-grip pull-up is the royal exercise for back muscles and biceps. Builds a strong, wide back and develops exceptional grip strength. An exercise that separates serious athletes from beginners.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":["Biceps","Shoulders","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S6","stretching":"T4","back":"P10","biceps":"S8","forearms_(front)":"S6"}},{"id":"pull_up_wide_grip","name":"pull_up_wide_grip","description":"The wide-grip pull-up maximally focuses on the latissimus dorsi, creating the characteristic V-shape of the body. A wider grip reduces the biceps contribution and forces the back to work harder. The ultimate upper body strength challenge.","difficulty":8,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Back","secondary_muscles":["Shoulders","Biceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S7","stretching":"T4","back":"P10","biceps":"S6","forearms_(front)":"S6"}},{"id":"push_up_and_rotation","name":"push_up_and_rotation","description":"A dynamic push-up variation combining upper body strength with core stability. After each rep, you open to the side, improving spinal mobility and engaging the oblique abdominal muscles.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Shoulders","Triceps","Abs / Core"],"muscle_i