riceps":"S4","legs_quads":"S5","glutes":"S4","stretching":"T2","back":"S3","cardio":"T3"}},{"id":"star_crunches","name":"star_crunches","description":"An explosive core exercise combining stretch and contraction. By touching the opposite hand and foot in the air, you will strengthen both the upper and lower abdominal muscles.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Legs – Quads"],"muscle_intensity":{"abs_/_core":"P9","legs_quads":"S4","stretching":"T2","cardio":"T2"}},{"id":"star_jump","name":"star_jump","description":"A high-intensity plyometric exercise for the whole body. The star jump will quickly raise your heart rate and build explosive leg strength.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":["Legs – Quads","Glutes","Calves","Abs / Core"],"muscle_intensity":{"abs_/_core":"S6","shoulders":"S4","calves":"S7","legs_quads":"P8","glutes":"S7","legs_hamstrings":"S5","cardio":"P10"}},{"id":"stepmill_machine_steps","name":"stepmill_machine_steps","description":"Continuous stair climbing for steel glutes and legs. The machine simulates natural upward movement, which is one of the best ways to shape the lower body.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Glutes","secondary_muscles":["Legs – Quads","Calves","Cardio"],"muscle_intensity":{"abs_/_core":"S3","calves":"S6","legs_quads":"P9","glutes":"P10","legs_hamstrings":"S6","cardio":"P9"}},{"id":"straight_bar_cable_pull_down","name":"straight_bar_cable_pull_down","description":"Isolation for the latissimus dorsi with straight arms. An excellent exercise for improving posture and emphasizing the 'V' shape of your back.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":["Triceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S4","chest":"T2","triceps":"S7","stretching