":"P10"}},{"id":"suspension_trainer_with_grips_abdominal_fallout","name":"suspension_trainer_with_grips_abdominal_fallout","description":"An extreme core strength exercise on suspension straps. By leaning forward, you create enormous torque on the abdominal muscles, which must stabilize the entire body.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Triceps","Chest"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S7","chest":"S5","triceps":"S6","glutes":"S5","stretching":"T2","back":"S4","forearms_(front)":"T2"}},{"id":"tricep_extension_machine","name":"tricep_extension_machine","description":"A machine for complete tricep isolation without the need for core stabilization. Allows safe and effective strengthening of the back of the arms through the full range of motion.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":["Forearms (Front)"],"muscle_intensity":{"abs_/_core":"T2","shoulders":"S3","triceps":"P10","stretching":"T2","forearms_(front)":"S4"}},{"id":"tricep_rope_extension_on_crossover_machine","name":"tricep_rope_extension_on_crossover_machine","description":"A popular cable machine exercise for tricep definition. Using a rope allows a greater range of motion at the bottom, leading to better activation of the lateral head of the tricep.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":["Forearms (Front)","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"S3","triceps":"P10","forearms_(front)":"S4"}},{"id":"triceps_dip_machine","name":"triceps_dip_machine","description":"A seated simulation of the parallel bar dip. The exercise is ideal for safely adding greater loads in tricep and chest training.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Triceps","secondary_muscles":["Chest","Shoulders"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S5","chest":"S6","triceps":"P10","stretching":"T2","back":"S3"}},{"id":"triceps_light_stretch","name":"triceps_light_stretch","description":"A relaxation exercise for lengthening the tricep fibers after an intense workout. Increases shoulder joint mobility and reduces muscle tension.","difficulty":2,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Stretching","secondary_muscles":["Triceps","Shoulders"],"muscle_intensity":{"shoulders":"S4","triceps":"P10","stretching":"P10","back":"S3"}},{"id":"upper_back_stretch","name":"upper_back_stretch","description":"Targeted stretching of the upper back muscles and the area between the shoulder blades. An excellent solution for releasing tension caused by prolonged sitting.","difficulty":2,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Stretching","secondary_muscles":["Back","Shoulders"],"muscle_intensity":{"shoulders":"S4","stretching":"P10","back":"P9"}},{"id":"upright_row_barbell","name":"upright_row_barbell","description":"A top exercise for developing the shoulder girdle and upper back. By pulling the weight vertically along the body, you will achieve that powerful shoulder appearance and improved muscle definition.","difficulty":6,"category":"strength","equipment":["weights"],"primary_muscle":"Shoulders","secondary_muscles":["Back","Biceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","shoulders":"P10","glutes":"T2","back":"S8","biceps":"S5","forearms_(front)":"S4"}},{"id":"v_bar_lat_pull_down","name":"v_bar_lat_pull_down","description":"A narrow-grip exercise that focuses on back depth and bicep strength. The neutral grip allows a more natural wrist position and maximum contraction of the back muscles.","difficulty":5,"category":"strength","equipment":["weights"],"primary_muscle":"Back","secondary_muscles":["Biceps","Shoulders","Forearms (Front)"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"S4","chest":"T2","glutes":"T2","stretching":"T2","back":"P10","biceps":"S7","forearms_(front)":"S5"}},{"id":"v_crunches","name":"v_crunches","description":"An intense abdominal exercise where the torso and legs meet in a V shape. Requires excellent balance and full core strength for proper execution.","difficulty":6,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Legs – Quads"],"muscle_intensity":{"abs_/_core":"P10","legs_quads":"S5","stretching":"T2","cardio":"T2"}},{"id":"v_up","name":"v_up","description":"An explosive crunch variation targeting the upper and lower rectus abdominis simultaneously. This exercise will quickly sculpt your abs and improve athletic stability.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Legs – Quads","Shoulders"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S3","legs_quads":"S6","stretching":"T3","cardio":"T2"}},{"id":"walking","name":"walking","description":"The most natural form of movement for improving overall health and endurance. Regular walking helps regulate body weight and reduces stress.","difficulty":2,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":["Legs – Quads","Calves","Glutes"],"muscle_intensity":{"abs_/_core":"T2","calves":"S4","legs_quads":"S4","glutes":"S3","legs_hamstrings":"S3","back":"T2","cardio":"P6"}},{"id":"walking_fast","name":"walking_fast","description":"Fast walking is a great way to raise heart rate without too much joint pressure. Increasing the pace will strengthen your heart and burn more energy than regular walking.","difficulty":3,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Cardio","secondary_muscles":["Legs – Quads","Calves","Glutes"],"muscle_intensity":{"abs_/_core":"S3","shoulders":"T2","calves":"S6","legs_quads":"S6","glutes":"S5","legs_hamstrings":"S4","back":"S3","cardio":"P9"}},{"id":"walkout","name":"walkout","description":"A dynamic exercise connecting upper body strength and leg flexibility. By 'walking' out on your hands from a standing position to a plank, you will awaken the entire body.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Shoulders","Triceps","Legs – Hamstrings"],"muscle_intensity":{"abs_/_core":"P9","shoulders":"S7","chest":"S5","triceps":"S6","legs_quads":"S4","legs_hamstrings":"T4","stretching":"T4","back":"S4","cardio":"T3"}},{"id":"wall_sit_bodyweight","name":"wall_sit_bodyweight","description":"An isometric challenge that will leave your legs 'on fire'. Leaning against a wall in a squat position builds strength endurance and knee joint stability.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Legs – Hamstrings","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","calves":"T2","legs_quads":"P10","glutes":"S7","legs_hamstrings":"S5","back":"T2","cardio":"T2"}},{"id":"wall_squat_bodyweight","name":"wall_squat_bodyweight","description":"Safe and controlled squatting with wall support. An ideal exercise for learning proper form and strengthening the legs without excessive spinal load.","difficulty":4,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Legs – Quads","secondary_muscles":["Glutes","Legs – Hamstrings","Abs / Core"],"muscle_intensity":{"abs_/_core":"S4","calves":"S3","legs_quads":"P10","glutes":"S7","legs_hamstrings":"S5","cardio":"T2"}},{"id":"wide_push_ups_bodyweight","name":"wide_push_ups_bodyweight","description":"A wide hand placement in push-ups maximally loads the chest muscles and the outer shoulders. An excellent choice for those who want to expand the chest and increase pushing strength.","difficulty":5,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Chest","secondary_muscles":["Shoulders","Triceps","Abs / Core"],"muscle_intensity":{"abs_/_core":"S5","shoulders":"S7","chest":"P10","triceps":"S6","stretching":"T2","back":"S3","cardio":"T2"}},{"id":"wind_wipers","name":"wind_wipers","description":"An advanced exercise for the lateral abdominal muscles that simulates windshield wiper movement. Controlled lowering of the legs will improve rotational core strength and back stability.","difficulty":7,"category":"strength","equipment":["bodyweight"],"primary_muscle":"Abs / Core","secondary_muscles":["Back","Shoulders","Legs – Quads"],"muscle_intensity":{"abs_/_core":"P10","shoulders":"S5","legs_quads":"S4","glutes":"S4","stretching":"T4","back":"S5","cardio":"T2"}},{"id":"wrist_curl_barbell","name":"wrist_curl_barbell","description":"A specialized exercise for developing the inner forearm and grip strength. Essential for those who want a more stable wrist and a stronger squeeze in other weighted exercises.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Forearms (Front)","secondary_muscles":["Biceps"],"muscle_intensity":{"stretching":"T3","biceps":"S3","forearms_(front)":"P10"}},{"id":"wrist_curl_dumbbell","name":"wrist_curl_dumbbell","description":"A unilateral forearm exercise that allows you to correct strength asymmetries between the left and right arm. Dumbbells will give you better focus on each forearm separately.","difficulty":4,"category":"strength","equipment":["weights"],"primary_muscle":"Forearms (Front)","secondary_muscles":["Biceps"],"muscle_intensity":{"stretching":"T3","biceps":"S3","forearms_(front)":"P10"}}]$openexercisedb$::jsonb) AS source(id TEXT, name TEXT, description TEXT, difficulty INT, category TEXT, equipment TEXT[], primary_muscle TEXT, secondary_muscles TEXT[], muscle_intensity JSONB)
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, difficulty=EXCLUDED.difficulty, category=EXCLUDED.category, equipment=EXCLUDED.equipment, primary_muscle=EXCLUDED.primary_muscle, secondary_muscles=EXCLUDED.secondary_muscles, muscle_intensity=EXCLUDED.muscle_intensity, updated_at=NOW();

-- Replace the legacy shared catalog while preserving trainer-owned movements.
CREATE TEMP TABLE legacy_shared_movement_ids (id UUID PRIMARY KEY) ON COMMIT DROP;
INSERT INTO legacy_shared_movement_ids (id) SELECT id FROM movements WHERE trainer_id IS NULL AND source_exercise_id IS NULL;
DELETE FROM template_exercises WHERE movement_id IN (SELECT id FROM legacy_shared_movement_ids);
UPDATE program_sessions SET prescription=jsonb_set(prescription, '{exercises}', COALESCE((SELECT jsonb_agg(exercise) FROM jsonb_array_elements(COALESCE(prescription->'exercises','[]'::jsonb)) exercise WHERE NOT EXISTS (SELECT 1 FROM legacy_shared_movement_ids legacy WHERE legacy.id::text=exercise->>'movementId')), '[]'::jsonb)) WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(prescription->'exercises','[]'::jsonb)) exercise JOIN legacy_shared_movement_ids legacy ON legacy.id::text=exercise->>'movementId');
UPDATE sessions SET prescription=jsonb_set(prescription, '{exercises}', COALESCE((SELECT jsonb_agg(exercise) FROM jsonb_array_elements(COALESCE(prescription->'exercises','[]'::jsonb)) exercise WHERE NOT EXISTS (SELECT 1 FROM legacy_shared_movement_ids legacy WHERE legacy.id::text=exercise->>'movementId')), '[]'::jsonb)) WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(prescription->'exercises','[]'::jsonb)) exercise JOIN legacy_shared_movement_ids legacy ON legacy.id::text=exercise->>'movementId');
DELETE FROM movements WHERE id IN (SELECT id FROM legacy_shared_movement_ids);
